import icontract


@icontract.ensure(lambda result: result >= 0)
@icontract.ensure(lambda s, result: result == len([c for c in s if '0' <= c <= '9']))
def countDigits(s: str) -> int:
    count = 0
    for c in s:
        if '0' <= c <= '9':
            count += 1
    return count
